      "body": "예수님이 붙잡히시기 전, 제자들과 제자들이 전하는 이야기를 듣고 믿게 될 사람들이 아버지와 아들의 사귐처럼 하나 되기를, 그래서 세상이 알아보기를 구하는 기도예요. 조선예수교연합공의회, 한국기독교교회협의회, 공동번역 성서, 그리스도인 일치 기도, 1984년 서울 방문, 한국기독교 100주년 선교대회, 교회 일치 같은 말로 찾을 수 있어요.",
