            "t": "1784년 봄, 이승훈이 북경에서 돌아왔습니다. 짐 속에는 서양 신부들에게서 받은 교리 책과 신앙에 쓰는 물건들이 들어 있었습니다.\n\n그는 북경에서 40일쯤 머물며 선교사들에게 글을 써 가며 교리를 배웠습니다. 그해 2월쯤 세례(물로 씻으며 교회의 한 식구가 되는 예식)를 받았습니다. 이 땅 사람으로는 처음 받은 세례입니다.¹\n\n이 먼 길에는 까닭이 있었습니다. 이 땅에는 세례를 줄 신부(교회의 예식을 맡은 사제)가 한 사람도 없었습니다. 신부가 이 땅에 처음 들어온 것은 10년 뒤인 1794년입니다. 이벽이라는 선비가 이승훈에게 북경에서 세례를 받아 오라고 권하고, 받는 절차도 일러 주었습니다.¹\n\n이 선비들은 그전부터 책을 읽고 있었습니다. 『천주실의』는 유교 경전을 끌어다 하나님을 설명한 한문 책이고, 『칠극』은 일곱 가지 죄를 이기는 길을 적은 책입니다. 두 책은 사신 행렬을 따라 조선에 들어와 선비들 손에서 손으로 읽혔습니다. 이벽은 당시 학문의 답에 만족하지 못하고 새 길을 찾던 사람이었고, 이승훈도 『천주실의』를 읽다가 믿음에 이르렀습니다.²\n\n1784년 초겨울, 서울 수표교 근처에 있던 이벽의 셋집에서 이승훈은 이벽과 권일신 등에게 세례를 주었습니다. 이 모임에서 이 땅 천주교회가 시작되었습니다. 신부 한 사람 없이, 책을 읽던 사람들이 서로를 교회로 불러 모은 것입니다. 1984년에는 천주교회의 지도자 요한 바오로 2세도 이 첫 모임이 신부가 아닌 일반 신자들만으로 세워졌다는 점을 짚었습니다.³",
