            "t": "이벽의 셋집은 모이는 사람이 늘자 좁아졌고, 눈에 덜 띄는 곳이 필요해졌습니다. 그래서 모임은 서울 명례방 동네에 있던 김범우의 집으로 옮겨 갔습니다. 이 모임을 명례방공동체라고 부릅니다.⁴\n\n김범우는 중국말 통역을 맡은 관리(역관)였고, 양반 아래 신분인 중인이었습니다. 그의 집에는 『천주실의』와 『칠극』 같은 책이 있었습니다. 신분을 가리지 않고 서양에서 온 책에 마음이 간 사람들이 이 집을 찾았습니다. 김범우의 권유로 최인길과 최필공 같은 중인들도 믿음을 받아들였고, 그는 두 동생에게도 믿음을 전했습니다.⁴\n\n이승훈은 북경에서 받아 온 교리 책을 공부하는 이들과 몇 달 동안 함께 읽고 이야기를 나누었습니다. 이벽이 사람들 앞에서 가르침을 풀어 주는 날도 있었습니다. 모임은 정해진 때에 다시 열리는 가르침의 자리가 되어 갔고, 세례를 받은 사람은 몇 달 사이에 수십 명이 되었습니다.⁴\n\n1785년 봄, 양반과 중인 여럿이 이벽의 가르침을 듣던 자리에 법을 집행하는 관청의 관리가 들어섰습니다. 관리는 노름판인 줄 알고 들어왔다가 모임의 모습을 보게 되었습니다. 관청의 책임자는 양반 집 아들들은 타일러 돌려보내고, 집주인 김범우는 붙들어 두었습니다.⁵\n\n김범우는 신앙을 버리라는 요구를 따르지 않았습니다. 심문에서는 서양 학문에 좋은 점이 많다고 답했고, 먼 고을로 귀양 가서 1년 뒤 그곳에서 세상을 떠났습니다.⁵ 이 자리에 관해 남은 기록은 여기까지이고, 명례방의 모임은 한동안 멈추었습니다. 그러나 믿는 사람들은 그 뒤에도 늘어 갔습니다."
