            "t": "이 첫 신자들은 읽기만 하지 않고 직접 쓰기도 했습니다. 정약용은 1784년 4월, 한강의 배 위에서 이벽에게 세상이 어떻게 시작되었는지와 사람의 영혼이 어찌 되는지를 처음 듣고 놀랐다고 적었습니다. 그 뒤 서울에서 이벽을 찾아가 『천주실의』와 『칠극』을 빌려 읽었습니다.⁶ 책이 사람을 부르고, 그 사람이 다시 책을 건네는 모양입니다.\n\n이벽은 성경 이야기를 한시(한자로 쓴 시)로 옮긴 『성교요지』를 남겼습니다. 앞쪽은 구약과 신약의 이야기를 시로 읊었고, 뒤쪽은 로마서를 중심으로 바른 길을 풀었습니다. 성경과 유학의 말을 함께 엮은 글입니다. 선비들은 자기들이 익숙한 글의 그릇에 새 믿음을 담아 본 것입니다.⁷\n\n정약종은 1797년에서 1799년 무렵 순한글로 『주교요지』를 썼습니다. 한자를 모르는 백성과 부녀자도 읽게 하려는 뜻이었습니다. 앞부분은 하나님이 계신다는 것을 풀고, 뒷부분은 예수 그리스도가 오신 일과 구원을 풀어 줍니다. 참고한 것은 주로 한문 서학서였고, 『천주실의』도 그 가운데 있었습니다.⁷ 한문 책이 선비의 방에 머물렀다면, 이 책은 같은 이야기를 모두의 글자로 옮겨 놓았습니다.\n\n그러나 믿는 일은 곧 시험을 만났습니다. 북경의 주교가 조상 제사를 금한다는 뜻을 전해 오자, 이승훈은 효를 가장 큰 도리로 여기던 세상에서 어느 쪽을 따를지 괴로워했고 한동안 교회를 떠났습니다.⁷ 이 물음은 다음 과로 이어집니다. 아래 표는 세 글이 답하려던 물음을 모은 참고이고, 줄의 순서에 뜻은 없습니다.\n\n| 글 | 답하려던 물음 | 그 뒤의 모습 |\n| --- | --- | --- |\n| 정약용의 글(1784년 4월의 일) | 책을 읽던 선비는 믿음 이야기를 어떻게 처음 만났나 | 『다산시문집』의 묘지명(죽은 이를 기리는 글)에 실림 |\n| 『성교요지』 | 성경 이야기를 선비의 글로 어떻게 옮길까 | 이벽의 글로는 이것 하나만 전함 |\n| 『주교요지』 | 한자를 모르는 사람에게 믿음을 어떻게 알릴까 | 손으로 베껴 전하다 1864년 처음 인쇄됨 |"
