            "t": "사도행전 8장은 예루살렘 교회가 어려움을 만나 신자들이 사방으로 흩어진 때의 이야기입니다. 흩어진 사람들은 가는 곳마다 기쁜 소식을 전했고, 빌립도 그 가운데 한 사람이었습니다.\n\n26~29절에서 주님의 천사가 빌립에게 예루살렘을 떠나 남쪽 길로 나서라고 합니다. 그 길에서 빌립은 에티오피아 여왕을 섬기는 높은 관리를 만납니다. 나라의 재물을 맡은 사람으로, 예루살렘에 예배하러 갔다가 돌아가는 길이었습니다. 그는 수레에 앉아 이사야서를 읽고 있었고, 성령은 빌립에게 그 수레 곁으로 가라고 하십니다.\n\n30~35절에서 빌립이 읽는 것을 이해하느냐고 묻자, 그는 누가 풀어 주지 않으면 어떻게 알겠느냐고 답하며 빌립을 수레에 앉힙니다. 그가 읽던 곳은 끌려가면서도 입을 열지 않는 이를 노래한 대목이었고, 그는 이 말이 누구를 가리키는지 묻습니다. 빌립은 바로 그 대목에서 시작해 예수에 관한 기쁜 소식을 전합니다. 36~40절에서 그는 길가의 물을 보고 세례를 청해 받고, 기쁘게 제 길을 갑니다.",
