            "t": "빌립의 물음은 짧습니다. 읽는 것을 이해하고 있느냐는 물음입니다. 에티오피아 사람은 글을 읽을 줄 알았지만, 누가 풀어 주어야 알겠다고 답합니다. 빌립은 서둘러 가르치려 하지 않고 그가 읽던 줄에서 이야기를 시작합니다. 읽는 책과 풀어 주는 사람이 한 수레 안에서 만난 것입니다.\n\n1984년 서울에서 열린 미사의 강론은 누가복음 24장의 엠마오 길 이야기를 불러옵니다. 그러고는 예수 그리스도의 진리가 중국에서 들어온 책으로 이 땅에 먼저 닿았다고 말합니다. 북경에서 세례를 받아 온 이승훈과 『천주실의』를 읽던 선비들, 한글로 『주교요지』를 쓴 정약종의 모습은 빌립의 수레와 닮았습니다. 읽는 책이 있었고, 풀어 주는 사람이 있었고, 서로 묻는 자리가 있었습니다.\n\n우리와 같은 것, 다른 것. 이 땅의 첫 신자들은 교리서와 한문 책을 읽으며 믿음을 찾았고, 오늘 한국 교회들은 성경을 읽습니다. 읽는 책은 달라도, 책을 놓고 서로 묻고 풀어 주며 믿음을 찾는 모습은 우리와 같습니다. 천주교와 개신교가 함께 받아 온 니케아-콘스탄티노플 신경도 같은 믿음의 바탕입니다. 다른 것은 이 이야기의 교회가 천주교회라는 점입니다. 우리 교회가 속한 개신교는 이 일이 있고 한참 뒤에 이 땅에 들어옵니다(4과).⁸\n\n이 시대에서 배울 점. 신부 없이 책 한 권을 놓고 묻고 풀어 주던 모습이 있었습니다. 양반과 중인이 한 방에 앉았던 일도 있었습니다. 이 둘은 이 시대 사람들이 남긴 선물입니다. 성경을 함께 읽는 우리 모임에서도 풀어 주는 사람과 풀이를 구하는 사람이 서로에게 선물이 됩니다.",
