            "t": "1. 이승훈 이야기는 아래 두 사전 항목을 따른다. 북경에서 40일쯤 머물며 선교사들에게 필담으로 교리를 배운 일은 『한국민족문화대백과사전』 「이승훈」의 서술이다. 이승훈이 북경에 든 것은 1783년 말이고, 북경에서 그랑몽(Grammont) 신부에게 세례를 받은 것은 1784년 2월쯤, 세례명은 베드로, 귀국은 1784년 3월 말이며 교리 책과 물건을 가져왔다: 한국교회사연구소 편, 『한국가톨릭대사전』 「이승훈」; 『한국민족문화대백과사전』 「이승훈」(백과사전 항목). 항목마다 북경에 든 해(1783)와 세례 받은 해(1784)가 따로 적히기도 해서, 이 책은 세례를 1784년으로 쓴다. 이벽의 권유와 세례 절차를 일러 준 일: 『한국민족문화대백과사전』 「이벽」, 『한국가톨릭대사전』 「이승훈」. 이 땅에 신부가 처음 들어온 것은 1794년 12월 주문모 신부: 성광동, 「｢황사영백서｣의 현대적 의미 고찰」, 『한국학』 46권 2호(2023).\n2. 『천주실의』(마테오 리치, 북경, 한문, 1603)와 『칠극』(판토하, 1614)이 조선에 들어와 읽힌 일, 이벽·권일신·정약용·이승훈이 『천주실의』를 통해 신앙에 이른 일: 『한국민족문화대백과사전』 「천주실의」, 「칠극」. 이벽이 당시 학문에 만족하지 못하고 새 사상을 찾은 일: 같은 책 「이벽」.\n3. 1784년 초겨울 이벽의 셋집에서 첫 세례: 『한국민족문화대백과사전』 「명례방공동체」; 『한국가톨릭대사전』 「이승훈」(1784년 겨울). 이 모임을 한국 천주교회의 창설로 보는 것도 두 항목의 설명이다. 요한 바오로 2세, 1984년 5월 6일 서울 여의도 시성 미사 강론(교황청 누리집 공개 본문): 진리가 중국에서 들어온 책으로 먼저 왔고, 1784년 북경에서 세례를 받은 일이 이 땅 첫 모임의 씨앗이며, 이 모임은 신부가 아닌 평신도들만으로 세워졌다는 말.\n4. 모임 장소가 이벽의 셋집에서 명례방의 김범우의 집으로 옮겨진 일(모임이 늘어 좁아지고 눈에 덜 띄는 곳이 필요해서), 이승훈이 교리서를 정독하고 토론한 일, 몇 달 사이 수십 명이 세례를 받은 일: 『한국민족문화대백과사전』 「명례방공동체」. 김범우의 신분과 집에 책이 있었고 신분을 가리지 않고 찾아온 일: 같은 책 「김범우」. 이벽이 사람들 앞에서 강론한 일: 같은 책 「이벽」, 「김범우」.\n5. 1785년 봄 양반과 중인이 이벽의 강론을 듣던 중 형조의 관리가 노름을 하는 줄 알고 들어갔다가 모임을 알게 된 일은 이기경의 『벽위편』을 인용한 『한국민족문화대백과사전』 「명례방공동체」의 설명이다(이 일을 을사추조적발사건이라 부른다). 양반 자제는 풀려나고 김범우가 갇힌 일(김범우 항목은 최인길도 갇혔다가 10여 일 뒤 풀려났다고 적는다), 신앙을 버리라는 요구를 따르지 않고 심문에서 서학에는 좋은 점이 많다고 답한 일, 유배, 1년 만에 세상을 떠난 일, 이 일 뒤에도 믿는 사람이 늘어 간 일: 같은 책 「김범우」, 「명례방공동체」. 유배지는 한때 단양으로 알려졌으나 밀양으로 확인되어 가고 있다(같은 책 「김범우」).\n6. 정약용이 1784년 4월 이벽에게서 천지창조와 영혼 이야기를 처음 듣고, 서울에서 이벽의 집을 찾아 『천주실의』와 『칠극』을 빌려 본 일: 백민정, 「왜 귀신의 공공성인가?」, 『창작과비평』(『다산시문집』 15권 「선중씨묘지명」을 인용한 설명); 주호식, 「정약용과 천주교의 관계 재론: 자찬묘지명을 중심으로」(1784년 4월 배 위에서 처음 들음).\n7. 이벽 『성교요지』(전반은 신구약을 바탕으로 한 한시, 후반은 로마서를 중심으로 한 글, 현존하는 유일한 저작, 기독교 사상과 유학 사상을 결합했다는 평가): 『한국민족문화대백과사전』 「이벽」. 정약종 『주교요지』(1797~1799년 무렵 저술, 주로 한문 서학서와 『성경직해』를 참고하고 『교요서론』, 『천주실의』, 『진도자증』을 특히 참조, 한자를 모르는 일반 백성과 부녀자를 위해 순한글, 상편 천주 존재와 속성·영혼, 하편 창조와 구원, 처음 필사본으로 전하다 1864년 목판본으로 간행): 같은 책 「주교요지」. 북경에서 돌아온 윤유일이 조상 제사를 금한 북경 주교의 명을 전하자 이승훈이 유교의 예와 교회법 사이에서 고민하다 교회를 다시 떠난 일: 같은 책 「이승훈」. 이벽도 효 윤리와 천주교 사이에서 갈등했다고 전한다(같은 책 「이벽」).\n8. 니케아-콘스탄티노플 신경(381)은 천주교와 개신교가 함께 받아 온 믿음의 글이다(Schaff, 『기독교 세계의 신경』 1권, CCEL). 개신교가 이 땅에 들어온 이야기는 4과에서 다룬다."
