            "t": "깊은 산골, 여러 고을의 경계가 맞닿은 곳에 신자들이 모여 사는 마을이 있었습니다. 박해가 나면 이웃 고을로 몸을 피해 붙잡히기를 면하기 쉬운 자리였습니다.\n\n이런 마을을 교우촌이라 불렀고, 1791년 진산의 일 뒤에 생기기 시작해 1801년과 1839년의 박해 뒤에 더 멀리 퍼졌습니다. 광주와 용인, 이천에 걸친 경기도 태화산 자락 같은 곳이 이런 마을로 이름났습니다.⁵\n\n사람들은 땅이 거친 곳에서 담배 농사를 짓고 옹기를 구우며 가난하게 살았습니다. 마을은 회장(신자들을 이끄는 일반 신자 지도자)을 중심으로, 신분을 따지지 않고 가진 것을 나누며 함께 살았습니다. 명예와 재산과 편안함을 좇지 않으려 애썼습니다. 프랑스 신부 달레는 박해가 오히려 믿음의 씨앗을 더 멀리 퍼뜨린 셈이라고 적었습니다.⁵\n\n1836년부터는 프랑스에서 온 신부들이 전국에 숨어 믿는 신자들을 찾아다녔습니다. 신부가 찾아간 마을은 공소(신부가 늘 머물지 못하는 곳에서 신자들이 모이는 작은 모임 자리)가 되었고, 신부가 회장을 임명하거나 인정했습니다. 신부는 주일과 교회가 지키는 큰 날에 모이는 일, 혼인과 장례, 다툼이 생겼을 때 판단하는 길에 대한 규칙도 세웠습니다.⁵\n\n주일과 큰 날이 되면 마을 사람들은 신분의 구별 없이 한자리에 모였습니다. 복음과 옛 믿음의 어른들의 가르침을 외우려고 애썼고, 서로 베푸는 사랑이 컸습니다.⁵ 이 자리에서 남은 기록은 여기까지이고, 어떤 말이 오갔는지는 전하지 않습니다."
