            "t": "1. 1791년 진산사건(신해박해)에서 윤지충과 권상연이 제사를 거부하고 신주(조상의 이름을 적은 나무패)를 불태웠고 조정이 이를 부모를 저버리는 일로 보아 처벌한 일: 성광동, 「｢황사영백서｣의 현대적 의미 고찰」, 『한국학』 46권 2호(2023), 47~84쪽; 『한국민족문화대백과사전』 「교우촌」.\n2. 『순조실록』 2권, 순조 1년(1801) 1월 10일 정해, 「사학을 엄금하라고 대왕 대비가 하교하다」(국사편찬위원회 조선왕조실록, sillok.history.go.kr). 명의 내용: 믿는 이를 타일러 고치게 하고 고치지 않으면 역률로 다스림, 부모와 임금을 따르지 않게 해 인륜을 무너뜨린다는 이유, 백성을 걱정하는 마음.\n3. 정하상(1795~1839)이 정약종의 둘째 아들이고 정약용의 조카이며, 1801년 신유박해로 아버지와 맏형이 목숨을 잃었고, 어머니가 어린 정하상과 동생을 데리고 마재로 내려간 일, 20세 무렵 홀로 서울로 돌아와 조숙·권천례 부부의 집에 머문 일: 『한국민족문화대백과사전』 「정하상」. 정약종이 1801년 박해 때 사형을 받은 일: 같은 책 「주교요지」. 1839년 기해박해의 때: 같은 책 「기해박해」. 1866년에 시작된 병인박해: 같은 책 「병인박해」.\n4. 정약종이 신선의 길을 배우다가 천지가 다시 바뀔 때 신선도 사라진다고 따져 보고 영생의 가르침이 더 합당하다고 여겨 믿은 일: 위 성광동(2023)이 인용한 황사영 『백서』의 서술.\n5. 교우촌의 생김새와 생활(산골 경계에 자리, 담배 농사와 옹기, 회장 중심의 공동생활, 신분 차별 없이 재물을 나눔, 복음과 성인들의 가르침을 외우려 함), 1791년 진산 뒤의 시작과 1801년·1839년 뒤의 퍼짐, 1836년 이후 프랑스 선교사들이 마을을 공소로 정하고 회장을 임명하며 주일과 큰 축일의 모임, 장례와 혼인, 다툼의 판단에 대한 규칙을 세운 일, 달레가 박해를 복음의 씨를 더 멀리 날린 일로 평한 것(항목이 인용한 말): 『한국민족문화대백과사전』 「교우촌」. 병인박해는 1866년부터 1873년까지 이어졌고 1886년 한불조약 뒤 신앙의 자유를 얻어 갔다: 같은 책 「병인박해」.\n6. 정하상이 1816년 북경에 선교사를 청하고 이후 여러 차례 오갔으며 1836~1837년 프랑스 신부들이 들어오자 주교를 도운 일: 『한국민족문화대백과사전』 「정하상」. 정하상이 1839년 붙잡힐 것을 예상하고 글을 써 두었다가 붙잡힌 뒤 재상 이지연에게 전하게 한 일, 세 부분(천주의 존재와 십계, 부모와 임금을 저버리는 종교가 아니라는 변론, 조상 제사와 신주에 대한 짧은 글): 『한국민족문화대백과사전』 「상재상서」; 『한국가톨릭대사전』 「상재상서」. 1839년 11월 23일 헌종의 이름으로 반포된 글(조인영이 지음)이 하늘을 섬기는 일과 사람의 도리를 두고 천주교를 비판한 일: 『한국민족문화대백과사전』 「기해박해」, 「척사윤음」.\n7. 요한 바오로 2세, 1984년 5월 6일 서울 여의도 한국 순교자 시성 미사 강론(교황청 누리집 공개 본문)의 열일곱 살 이 아가타 이야기. 정하상이 1839년 세상을 떠났고 1984년 성인으로 선포된 일: 『한국민족문화대백과사전』 「정하상」.\n8. 시성은 1984년 요한 바오로 2세가 한 일이다(강론 본문; 『한국민족문화대백과사전』 「기해박해」)."
