            "h": "국경에서 시작된 번역",
            "t": "1874년, 스코틀랜드연합장로회가 보낸 선교사 존 로스는 압록강 가의 국경 도시 고려문에서 조선 상인들을 만났습니다.¹ 로스는 중국 동북쪽 만주에서 일하고 있었습니다. 이 만남이 그를 조선 사람들에게로 이끌었습니다.¹ 그해 가을 의주의 한 상인이 고려문에서 성경을 받아 집으로 가져갔고, 그 집 아들이 읽고 마음이 움직였습니다.²\n\n1876년 로스는 의주 사람 이응찬을 한국어 선생으로 맞아 한글을 배우며 성경을 옮기기 시작했습니다.¹ 왜 한글이었을까요? 공부한 사람은 한문 성경을 읽을 수 있었지만, 보통 사람은 한자를 읽지 못하고 한글은 쉽게 읽었기 때문입니다.³ 로스는 누구나 읽고 알아들을 말로 성경을 옮기려 했습니다.³\n\n1882년 심양에서 『예수셩교 누가복음젼셔』가 찍혔고 곧 요한복음이 뒤를 이었습니다.¹ 의주 사람 서상륜은 이 책들을 가지고 국경을 넘는 권서(성경을 팔고 나누는 사람)가 되었습니다.⁴ 책을 들여오다 붙잡혀 갇힌 일도 있었지만 그는 빠져나와 이야기를 이어 갔습니다.⁴\n\n서상륜은 동생과 함께 황해도 소래 마을로 옮겨 믿는 사람들의 모임을 이루었습니다. 그곳에는 한국 사람의 손으로 지은 교회가 섰습니다.⁴ 1887년에는 신약 전체를 담은 『예수셩교젼셔』가 나왔습니다.¹ 책이 쓰인 곳은 만주였지만 읽는 사람들은 이 땅에 있었습니다. 개신교 선교사들이 이 땅에 들어오기 전에, 한글 성경이 먼저 와 있었습니다.⁴ 말씀이 사람들 곁에 먼저 닿은 길은 이렇게 책과 한국 사람들의 발걸음으로 열렸습니다.",
