                "alt": "한국 교회가 걸어온 길을 보여 주는 그림. 가로 눈금은 1784, 1801, 1866, 1887, 1907, 1919, 1945, 1987년과 오늘이고 햇수와 간격이 맞지 않는다. 열두 과가 다루는 때가 막대 열두 개로 위에서 아래로 놓이고, 지금 읽는 4과(부활절의 제물포)의 막대만 노랗게 칠해져 있다. 막대 길이에 뜻이 없다. 사람은 없다.",
