            "t": "사도행전의 부름은 환상으로 왔고, 이 땅의 부름은 편지로 왔습니다. 이수정이 미국 교회에 보낸 편지는 「마케도니아인의 부름」이라는 이름으로 소개됩니다.² 둘 다 건너와서 도와 달라는, 먼저 도움을 청하는 목소리였습니다. 바울 일행은 환상을 본 뒤 함께 하나님의 부르심이라고 판단하고 건넜습니다. 한국에 온 개신교 선교사들 앞에도 편지와 함께, 한글 성경으로 믿게 된 사람들이 이미 있었습니다.⁴\n\n우리와 같은 것, 다른 것. 같은 것은 성경과, 천주교와 개신교가 함께 받아 온 니케아-콘스탄티노플 신경의 믿음입니다.⁸ 다른 것은 교회마다 이 땅에 들어온 때와 길이 달랐다는 점입니다. 장로교와 감리교는 1885년에 미국 교회의 선교회가 보낸 선교사가 시작했습니다. 성공회는 1890년에 영국 교회가 보낸 주교가, 동방에서 이어 온 정교회는 1900년에 러시아 교회가 보낸 사제가 시작했습니다.¹ ⁶\n\n처음 한 일도 달랐습니다. 장로교와 감리교는 병원과 학교로, 성공회는 한국의 말과 글을 배우는 일을 첫 일로 삼고 진료소도 함께 열었습니다.³ ⁶ 예배의 모양과 교회를 다스리는 방식도 서로 달랐습니다.\n\n이 시대에서 배울 점. 닫힌 문 앞에서 사람들의 필요를 돕던 끈기와, 교회가 그 땅 사람들의 힘으로 서야 한다고 생각한 마음은 이들이 남긴 글에서 읽히는 선물입니다. 도와 달라는 소리를 한 사람의 환상이나 편지에 두지 않고 함께 헤아려 응한 일행의 모습에서도 배웁니다. 교회마다 길은 달랐지만 모두 닫힌 문 앞에서 사람들 곁에 서려 했다는 점에서도 배웁니다. 먼저 믿은 이웃이 있었다는 사실 앞에서는 겸손해집니다.",
