            "h": "정동의 소녀와 열린 문",
            "t": "열 살이던 1887년, 서울 정동의 김점동은 이화학당에 들어갔습니다.¹ 이 학교는 한 해 전에 미국 감리교 선교사 스크랜턴 부인이 처음 열었습니다.² 선교사들은 왜 학교를 열었을까요? 한 연구는 성경을 가르치고 전도를 도울 여성, 교회 일과 통역과 간호를 맡을 사람을 길러 내려 했다고 정리합니다.³\n\n점동은 1890년 학교를 마친 뒤 정동의 병원 보구녀관에서 통역을 맡았습니다.¹ 이 병원은 1887년 이화학당 구내의 한옥을 고쳐 연, 여성 환자를 위한 병원이었고 입원실은 온돌방이었습니다. 고종이 이 병원에 '보구녀관'이라는 이름을 내렸다고 하며, 영어로는 '많은 아픈 여성들을 위한 집'으로 옮겨졌습니다.⁴ 한국에는 여성이 남자 의사가 있는 병원에 가기를 꺼리는 풍속이 있었고, 그래서 감리교 선교부는 여성만을 위한 병원을 세우기로 했습니다.⁴\n\n점동은 병원에서 의사 로제타 셔우드를 도우며 자기도 의사가 되고 싶다는 꿈을 품었습니다.¹ 셔우드는 여성의 의료는 여성이 맡아야 한다며 이화학당 학생 넷을 모아 의학 훈련반을 열었고, 점동은 그 훈련생 가운데 한 사람이었습니다.⁴ 세례를 받으며 에스더라는 이름도 얻었고, 혼인한 뒤에는 박에스더로 불렸습니다. 미국의 여자의과대학에서 공부해 1900년 의사가 되어 돌아왔습니다.¹\n\n돌아온 그는 다시 보구녀관에서 환자를 만났고, 먼 지방까지 다니며 진료했습니다. 위생을 가르치고 맹아학교 교사로도 일했습니다.¹ 한 소녀의 길에는 글을 배울 학교와 아픈 이를 만날 병원, 두 문이 있었습니다.",
