            "h": "정동 집의 첫 학생",
            "t": "1886년 5월 31일 밤, 서울 정동 스크랜턴 부인의 집에 한 아이가 학생으로 들어왔습니다. 가난한 집의 딸이었고, 부인은 아이의 어머니에게 아이의 몸을 책임지겠다는 약속의 글을 써 주었습니다.² 그해 부인은 초가 열아홉 채가 있던 터를 사서 학교 건물을 지었고, 건물은 11월부터 쓰였습니다.²\n\n학생은 처음에 셋뿐이었고, 둘째 학생은 부인이 집 문밖에서 만난 고아였습니다.³ 처음 몇 해 동안 학교에 온 아이들은 가난한 집 아이, 과부의 딸, 선교사 곁에서 일하는 한국 사람의 자녀였습니다.³ 양반집 딸에게는 집 안에 머무는 것이 지켜 주는 울타리였고, 신분이 낮은 아이들과 한자리에서 배우는 일도 꺼려졌기 때문입니다.³\n\n교실에서는 성경 같은 신앙의 책과 영어, 기초 글 읽기를 배웠습니다.³ 학교는 학생들이 교회 일과 통역과 간호를 맡게 하는 곳이면서 좋은 주부로 자라게 하는 곳이기도 했습니다.³ 처음에는 여성 선생들이 대부분의 과목을 가르쳤고, 한문은 남자 선생이 맡는 때도 있었습니다. 체조 수업은 바깥 사람들 사이에서 논란이 되었고, 학생들이 성문 밖으로 꽃놀이를 가는 날도 있었습니다.² 한글 교사로 부인의 일을 돕던 이경숙은 찾아온 손님에게 학교를 소개했습니다.²\n\n항목은 부인이 학생을 외국 생활양식에 맞추려는 것이 아니라 더 나은 한국인으로 기르려 한다고 밝혔다고 적습니다.² 1887년 학생이 일곱으로 늘었을 때 고종이 학교에 이름을 내렸습니다. 부인은 '온전히 믿고 맡긴다'는 뜻의 이름을 생각해 두었지만, 고마움을 담아 '이화'(배꽃)를 택했습니다.²"
