            "t": "1898년 9월 1일 서울의 양반 여성들이 '이소사'와 '김소사'라는 이름으로 통문(여럿이 돌려 읽도록 쓴 알림글)을 냈습니다. 황성신문과 독립신문에 실린 이 글은 세상이 새로워지는데 여성만 옛 관습에 머문다고 말합니다.⁵ 여성의 몸과 감각이 남자와 다르지 않은데도 평생 집 안에서 남에게 기대어 산다는 것입니다.⁵\n\n글은 옛 책을 내세워 여자는 바깥일을 말하지 말라고 해 온 일도 짚습니다. 그래서 여학교를 세워 어려서부터 여러 학문을 배우게 하자고 하고, 뜻있는 이들에게 딸을 보내 달라고 부탁합니다.⁵ '소사'는 이름이 아니라 부르는 말이었고, 혼인한 여성은 공식으로 이름 대신 '씨', '성', '소사' 같은 말로 불렸습니다.⁶ 글을 낸 이들은 찬양회라는 모임을 만들고 학교를 열었고, 모임의 임원들이 직접 가르쳤습니다.⁶\n\n선교 기록을 연구한 글은 선교사들이 여성 교육을 여성이 여성에게 복음을 전하는 길로 보았다고 정리합니다.³ 선교사들은 한국 여성 일꾼인 전도부인(돈을 받고 여성들을 찾아가 복음을 전한 사람)도 두었습니다. 언어와 풍습이 낯선 선교사가 한국 여성에게 직접 전하기 어려웠기 때문이라고 항목은 설명합니다. 이들은 처음에 안방의 여성을 찾아가 성경과 찬송가를 팔고 한글을 가르쳤습니다.⁷\n\n병원에도 이런 모습이 있었습니다. 보구녀관의 대기실에서는 성경 공부가 열렸고 주일에는 기도회가 있었습니다.⁴ 아래 표는 이 글들이 같은 시대에 답한 물음을 모은 참고이고, 줄의 순서에 뜻은 없습니다.\n\n| 물음 | 글 | 답의 요지 |\n| --- | --- | --- |\n| 왜 여학교가 필요한가 | 여학교 설시 통문(1898) | 세상이 새로워지는데 여성만 옛 관습에 머무니, 어려서부터 배우게 하자 |\n| 왜 여학교가 필요한가 | 선교 학교를 연구한 글(2021) | 성경을 가르치고 전도를 도울 여성, 교회 일과 통역과 간호를 맡을 사람을 기름 |\n| 왜 여성만의 병원인가 | 보구녀관 항목과 연구 논문 | 여성이 남자 병원에 가기를 꺼리는 풍속이 있어 여성 환자를 위해 세움 |"
