          {
            "id": "ce06-r2",
            "kind": "read",
            "h": "장대현교회의 겨울 저녁",
            "t": "평양의 사경회에는 여러 교회의 대표들이 왔습니다. 대부분 먼 길을 걸어왔고, 모두 자기 비용으로 오면서 수업료를 조금 냈습니다.³\n\n공부는 여덟 반으로 나뉘었고 사경회는 보통 1월의 첫 보름쯤 이어졌습니다. 하루는 아침 기도와 찬송으로 열었고, 반마다 세 시간씩 성경을 공부했습니다. 밤에는 장대현교회에서 남자들의 큰 모임이 열렸습니다. 선교사들은 낮에도 따로 모여 기도했습니다.³ ⁴\n\n어느 밤 모임을 이끌던 선교사 리가 사람들에게 말했습니다. 그렇게 기도하고 싶으면 모두 기도하라는 말이었습니다. 그러자 모인 사람들이 한꺼번에 소리 내어 기도했습니다. 블레어는 그 소리가 많은 물이 떨어지는 소리 같았다고 썼습니다. 오늘 통성기도(여럿이 한꺼번에 소리 내어 하는 기도)라 부르는 모습이 이 글에 남아 있습니다.³ ⁵\n\n이어서 사람들이 한 사람씩 일어나 자기 잘못을 고백하며 울었습니다. 한 사람은 선교사에게 자기 같은 사람도 용서받을 수 있느냐고 물었습니다. 블레어는 모임이 새벽 두 시까지 이어진 밤도 있었다고 씁니다.³\n\n또 어느 날 블레어의 조수가 한 장로를 미워했다고 고백했지만, 그 장로는 말이 없었습니다. 얼마 뒤 그 장로가 일어나 자기도 조수를 미워했고 블레어도 미워했다고 고백했습니다. 블레어는 그 곁에 엎드려 함께 울며 기도했고, 선교사 리가 찬송을 시작하자 노래 가운데 조용해졌습니다. 선교사들은 모임이 걷잡을 수 없어질까 의논했지만 막지 않았습니다.³ 백과사전 항목이 이 사경회의 계기로 적은 길선주의 회개는 이 글들에 적혀 있지 않습니다.¹"
          },
          {
            "id": "ce06-r3",
            "kind": "read",
            "h": "부흥 무렵 교회에 남은 일들",
            "t": "블레어는 책의 마지막 장에 '결과'라는 제목을 붙이고, 사경회가 끝난 뒤 사람들이 고백을 안고 각자의 마을로 돌아갔다고 씁니다. 평양의 여러 교회에서는 한 달이 넘게 특별 집회가 열렸고, 학교는 며칠 수업을 접고 아이들이 함께 자기 잘못을 말하며 울었다고 합니다.³\n\n사람들은 집집마다 찾아다니며 잘못을 말했고, 훔친 돈과 물건을 믿는 사람에게도 믿지 않는 사람에게도 돌려주었습니다. 한 중국 상인은 어느 신자가 찾아와 여러 해 전에 부당하게 얻은 큰돈을 갚자 놀랐다고 블레어는 적습니다.³\n\n1907년 가을 독노회(독립노회를 줄인 말)가 세워졌습니다. 노회는 여러 교회가 함께 일을 의논하는 장로교의 모임입니다. 네 장로교 선교부가 함께 세웠고(미국 남장로교와 북장로교, 호주 빅토리아주 장로교, 캐나다 장로교), 열두 조의 신조(믿는 바를 적은 글)를 채택했습니다. 평양신학교의 첫 졸업생 일곱이 목사가 되었고, 그 가운데 이기풍이 제주도 선교사로 가기로 했습니다.⁶\n\n그 무렵 교회 모임에 자리 잡은 것으로 새벽기도가 있습니다. 1906년 장대현교회에서 길선주가 장로 박치록과 함께 새벽기도를 시작했고, 교회가 날마다 새벽에 모여 잘못을 고백하고 부흥을 위해 기도했다는 설명이 전해집니다.⁷ 부흥운동의 예배사적 배경을 살핀 한 연구는 사경회, 평신도가 예배를 이끈 일, 즉흥 기도, 새벽기도, 통성기도, 철야기도를 부흥운동과 이어서 살핍니다.⁵ 아래 표는 이 글들이 답하는 물음을 모은 참고이고, 줄의 순서에 뜻은 없습니다.\n\n| 물음 | 글 | 답의 요지 |\n| --- | --- | --- |\n| 사경회 뒤에 사람들은 무엇을 했나 | 블레어의 책 | 잘못을 말하고 훔친 돈과 물건을 돌려줌 |\n| 교회는 무엇에 마음을 모았나 | 독노회를 다룬 백과사전 항목 | 신조를 정하고 첫 목사를 세우고 제주도로 선교사를 보냄 |\n| 새벽기도는 어디서 시작되었나 | 길선주를 다룬 글 | 1906년 장대현교회에서 길선주가 시작했다는 설명 |"
          }
