            "kind": "read",
            "h": "본문의 자리",
            "t": "누가복음 18장에서 예수님은 기도에 관한 비유를 연달아 말씀하십니다. 앞의 비유는 낙심하지 말고 기도하라는 말씀이고, 이 과의 비유는 그다음에 이어집니다. 9절은 이 비유를 들은 사람들을 소개합니다. 자기가 하나님 앞에서 바르다고 믿고 다른 사람을 낮추어 보는 몇 사람입니다.\n\n10~12절에서 두 사람이 기도하러 성전에 올라갑니다. 한 사람은 바리새파 사람(율법을 꼼꼼히 지키려 애쓴 사람들)이고, 다른 한 사람은 세리(세금을 거두던 사람)입니다. 바리새파 사람은 서서 혼자 말합니다. 자기는 다른 사람들과 같지 않아서 감사하다고 하며, 한 주에 두 번 음식을 끊고 번 돈의 열에 하나를 바친다고 내세웁니다.\n\n13절에서 세리는 저만치 떨어진 자리에 서 있습니다. 얼굴을 들지 못한 채 자기 가슴만 치면서 짧게 기도합니다. 하나님, 허물 많은 저를 가엾게 여겨 주세요. 14절에서 예수님은 두 사람 가운데 하나님 앞에서 바른 자리에 서서 집으로 돌아간 쪽이 이 세리라고 말씀하십니다. 자기를 크게 보는 사람은 작아지고 스스로 작게 서는 사람은 커진다는 말로 맺으십니다.",
