            "t": "1. 박명수, 「1907년 대부흥운동」, 한국민족문화대백과사전(1903년 여름 원산의 성경공부 모임과 하디의 고백, 하디의 집회, 1905년 9월 연합공의회의 결정, 1906년 1월 교파를 넘은 연합 부흥회, 1907년 1월 장대현교회 연합사경회, 길선주의 회개와 신자들의 고백, 부흥의 배경으로 거론되는 사정들).\n2. 김칠성, 「하디의 회개, 부흥의 원인인가, 결과인가?」, 『선교신학』 32, 2013, 175~199쪽 초록(하디의 회개를 부흥의 원인으로 보는 견해와 결과로 보는 논증. 같은 초록은 하디가 성경을 공부하며 부흥을 위해 기도했다고도 정리한다).\n3. William N. Blair, *The Korea Pentecost and Other Experiences on the Mission Field* (뉴욕, 미국 북장로회 해외선교부 발행), 9장 「평양 사경회」, 10장 「한국의 오순절」, 11장 「결과」(1906년 8월의 성경 공부, 사경회의 짜임, 저녁 집회, 소리 내어 한 기도, 고백, 장로와 선교사의 고백, 고백 뒤의 일들, 그해 가을의 독립 노회).\n4. G. Lee, “How the Spirit Came to Pyeng Yang,” *The Korea Mission Field* 3(3), 1907년 3월, 33~37쪽(1906년 8월 평양 성경 회의, 1907년 1월 저녁 연합 집회, 낮 기도 모임).\n5. 김경진, 「1907년 평양 대부흥운동의 예배사적 배경과 신학에 대한 연구」, 『신학과 실천』 12, 2007, 165~197쪽 초록(사경회, 평신도의 예배 인도, 즉흥 기도, 새벽기도, 통성기도, 철야기도).\n6. 민경배, 「독로회」, 한국민족문화대백과사전(1907년 독로회, 항목의 이름은 '독로회'이고 독립노회를 줄인 말, 네 선교부의 연합, 평양신학교 첫 졸업생 일곱의 안수, 이기풍의 제주도 파송).\n7. 강희창, 「길선주(1896-1935)」, *Journal of Korean American Ministries & Theology* 4, 2011, 13~20쪽(1906년 장대현교회의 새벽기도, 새벽 4시에 종이 울려 모인 일, 새벽기도 뒤 이십 분쯤 요한계시록을 외웠다는 서술). 이 설명은 김명혁의 책에 기대어 있고, 이말테, 「한국개신교회의 새벽기도의 초기에 대한 연구」, 『신학과 실천』 31, 2012, 183~225쪽 초록은 1890년 9월 등 더 이른 새벽기도 기록을 들어 새벽기도가 부흥 때 시작되었다는 설명을 다시 살핀다."
