            "t": "여럿이 함께 하는 일 앞에서 내 마음은 편치 않았던 적이 있나요? 그때 나는 어떻게 했나요?",
            "sub": "모임의 관습이나 학교와 일터의 작은 일도 좋아요. 이야기하고 싶은 만큼만 나눠요.",
            "vs": [],
