          {
            "id": "ce07-r2",
            "kind": "read",
            "h": "한 장면 · 1938년 9월 평양의 총회",
            "t": "1938년 9월, 평양의 서문밖교회에서 조선예수교장로회 제27회 총회가 열렸습니다. 노회(여러 교회가 모이는 회의)마다 보낸 대표들이 모인 자리였습니다. 그해 초에는 평양의 숭실전문과 숭의여학교 같은 기독교 학교들이 문을 닫은 일이 있었습니다.⁵ 이 총회의 결의를 두고 압박 속의 결정으로 읽는 글도 있고, 교회 스스로의 선택이 많이 섞였다고 읽는 글도 있습니다.⁷\n\n압박 속의 결정으로 읽는 글은 이런 사실을 짚습니다. 총회에 앞서 당국이 대표들에게 압력을 넣었고, 회의장에는 경찰이 있었으며, 반대하는 동의는 막혔다는 것입니다. 다만 두 글의 서술은 조금 다릅니다. 한 글은 당국이 몇몇 대표에게 미리 접근해 위협했다고 하고, 다른 글은 대표 모두가 경찰서에 불려 갔다고 합니다.⁷\n\n교회 스스로의 선택으로 읽는 한 글은 다른 사실을 듭니다. 평북노회가 그해 2월에, 평양노회가 8월에 총회보다 먼저 신사참배를 결의했습니다. 총회에서는 김길창이 당국과 조선 교회와 선교사들 사이의 관계를 원만하게 하자는 안을 냈습니다.⁷\n\n9월 10일에 신사참배를 결의했고, 총회장의 이름으로 성명서가 나왔습니다. 성명서는 신사참배를 애국적인 국가의식이라 부르고, 일본 제국의 신민으로서 정성을 다하겠다고 밝혔습니다. 같은 날 선교사와 대표 몇 사람이 항의했다는 기록이 남아 있습니다.⁷\n\n이 자리에서 남은 기록은 여기까지입니다. 말을 남기지 않은 대표가 대부분이었고, 그들의 마음은 어느 기록에도 없습니다."
          },
          {
            "id": "ce07-r3",
            "kind": "read",
            "h": "그들이 남긴 글 · 서로 다른 답",
            "t": "신사참배를 두고 세 곳의 글이 남아 있습니다. 첫째는 1938년 9월 10일 총회장 홍택기의 이름으로 나온 총회(교단 전체의 회의)의 성명서입니다. 성명서는 신사가 종교가 아니고 기독교 교리에 어긋나지 않는다고 이해했다고 적었습니다. 또 비상시국에서 신사참배를 앞서서 실행하며, 일본 제국의 신민으로서 나라에 정성을 다하겠다고 밝혔습니다.⁷\n\n둘째는 1936년 교황청이 일본의 교회들에 보낸 지침입니다. 신사의 예식에 나타나는 것은 나라를 사랑하는 뜻뿐이라고 설명하고, 신자들이 참여해도 된다고 가르치게 했습니다. 그 근거는 일본 정부가 신사 예식을 애국의 표현이라고 설명한 데 있었습니다. 조선의 천주교 주교들은 도쿄에서 허용되는 일은 조선에서도 허용한다고 정했습니다.⁴\n\n셋째는 주기철 목사의 말입니다. 총회보다 두 해 앞선 1936년, 평양 산정현교회에서 한 첫 설교로 전하는 말이 있습니다. 그 말에는 신사참배가 첫째 계명을 어기는 일이고 하나님을 배신하는 일이라는 뜻이 담겨 있습니다.⁶ 이는 본인이 쓴 글이 아니라 아들의 회고입니다. 그는 여러 번 붙잡혔습니다.⁶\n\n뒷날 장로교회는 이 결의를 다시 다루었습니다. 1946년 남부총회는 1938년의 결의를 취소했고, 1954년 총회는 취소와 함께 참회 기도회를 열었습니다.⁵ 이 일은 교단이 스스로 적은 연혁에 실려 있는 기록입니다.\n\n아래 표는 위 세 글의 답을 이 책이 줄여 모은 참고이고, 줄의 순서에 뜻은 없습니다.\n\n| 글 | 쓴 사람 | 답의 요지 |\n| --- | --- | --- |\n| 1938년 총회 성명서 | 장로교 총회 | 종교가 아닌 국가의식이므로 교리에 어긋나지 않는다 |\n| 1936년 교황청 지침 | 천주교 | 시민의 예식이므로 신자가 참여할 수 있다 |\n| 주기철의 말 | 한 목사 | 첫째 계명을 어기는 일이다 |"
          }
