            "lead": "왕의 요구가 한 번이 아니라 기회를 한 번 더 주는 모양이라는 점, 마지막에 \"어떤 신이 건지겠느냐\"는 물음이 있다는 점을 찾게 해 주세요. 왕의 말을 평가하지 않고 무엇이 적혀 있는지만 확인하면 충분해요."
