            "kind": "read",
            "h": "본문 설명 · 절하지 않겠다는 대답",
            "t": "세 사람의 대답은 길지 않지만 분명하며 두 갈래입니다. 하나는 하나님이 구해 내실 수 있다는 믿음이고, 다른 하나는 구해 주시지 않더라도 엎드리지 않겠다는 다짐입니다. 왕이 마지막으로 어떤 신이 너희를 건지겠느냐고 물었을 때, 그들은 결과가 어떻게 될지 알지 못한 채 섬길 분을 먼저 정했습니다. 왕의 명령은 신하로서 따르던 나라의 일이었지만, 세 사람은 그 안에 예배의 물음이 들어 있다고 보았습니다.\n\n한국 교회가 신사 앞에서 받은 물음도 같은 곳, 곧 누구를 예배하느냐는 물음을 건드렸습니다. 교황청의 지침도, 장로교 총회의 성명도, 주기철의 말도 신사 앞에 절하는 일을 예배에 비추어 말한 글입니다. 답은 서로 달랐습니다. 이 책은 어느 답이 옳은지 정하지 않고 그 글들이 말한 사정을 읽었습니다.\n\n우리와 같은 것, 다른 것. 같은 것은 성경과 니케아-콘스탄티노플 신경이 고백하는 한 분 하나님을 믿는 믿음입니다.⁸ 다른 것은 이 글들이 나라를 잃고 일본의 요구를 받던 시대의 사정 안에서 쓰였다는 점입니다.\n\n이 시대에서 배울 점. 그 시대 사람들은 자기 사정을 글로 남겼습니다. 이 과에서 읽은 세 글에는 서로 다른 답과 그렇게 답한 이유가 함께 적혀 있습니다. 나와 다른 답 앞에서 그 이유를 먼저 읽어 보는 일이 오늘 우리가 배울 점입니다. 이유를 읽는다고 그 답에 동의해야 하는 것은 아닙니다. 다만 읽어야 어떤 사정에서 그런 답이 나왔는지 비로소 알 수 있습니다.",
