            "t": "1. 독립선언서 본문과 서명자 33인 명단(길선주 포함), 공약삼장: 기미 독립선언서 한글 게시본. 선언 날짜와 장소(1919년 3월 1일, 서울 인사동 태화관의 별실): 김도형, 국가기록원 지정기록물 「3·1운동 관련 독립선언서류」 해설. 태화관에 실제로 모인 사람은 29인이었고 길선주를 포함한 4인은 지방에 있어 이름만 올린 일: 「태화관」, 한국민족문화대백과사전. 서명자의 종교 구성(천도교, 기독교, 불교)과 이승훈의 합류: 「3·1독립선언서」, 한국민족문화대백과사전.\n2. 이만열, 「3.1운동과 한국 교회」 강연문(기윤실 2019년 회원총회): 종교 집회가 가능했고 교단마다 지방 기구가 있었던 점(3쪽), 믿음과 나라를 잇는 눈, 독립을 바라는 알림글에 날마다 성경 읽기와 기도를 적은 일(7~8쪽).\n3. 일본 문부성이 신사참배를 애국심과 충성심의 표시라고 답한 일: 조현범, 「일제 강점기 조선 천주교회의 정체성」, 『정신문화연구』 25권 2호(2002), Ⅲ장 1절. 신사참배 강요가 학교에서 먼저 본격화된 일: 안종철, 『미국 북장로교 선교사들의 활동과 한미관계, 1931~1948』(서울대 박사논문, 2008), 국문초록.\n4. 1936년 5월 26일 교황청 포교성성의 지침 「Pluries instanterque」: 미요시 지하루, 「Shinto, Nationalism and the Catholic Church in the Early Showa Era」, 『신학과 철학』 18호, 35쪽. 조선 주교회의가 도쿄에서 허용되는 실천은 조선에서도 허용하도록 정한 일(시점은 확인하지 못함): 조현범(2002), Ⅲ장 1절.\n5. 1938년 9월 10일 제27회 총회의 신사참배 결의, 1946년 6월 12일 남부총회의 취소, 1954년 4월 26일 총회의 취소와 참회 기도회: 대한예수교장로회 총회 누리집 「총회연혁」(교단이 적은 자기 연혁). 1938년 9월 제27회 총회와 그해 초 평양의 기독교 학교들이 문을 닫은 일: 안종철, 「종교와 국가의례 사이」, 『한국학연구』 22집(2010), 36쪽.\n6. 주기철의 말: 서석훈, 「주기철」, 『Journal of Korean American Ministries & Theology』 4호(2011), 23쪽(1936년 산정현교회 첫 설교로 소개하고, 출처는 아들 주광조의 2004년 회고, 28쪽). 붙잡힌 횟수: 서석훈은 다섯 번 투옥, 박용규, 『신학지남』 83권 2호(2016)를 소개한 글(kich.org)은 세 번 체포로 적는다.\n7. 총회 장소와 날짜, 총회장 홍택기의 이름으로 낸 성명서(1938년 9월 10일), 같은 날 선교사와 대표 몇 사람이 항의했다는 기록: 『제27회 총회회의록』의 글을 전한 주간기독신문 보도를 옮겨 실은 개인 교회 누리집 게시본(nykcn.org) 한 곳에서만 확인했다. 압박의 읽기(학술 글 두 편): James H. Grayson, 「Religion, Nationalism and State Policy」, 『Japan Christian Review』 60(1994)(Blair 1977, 93을 인용; 당국이 대표 몇 사람을 미리 위협하고 경찰이 반대 동의를 막은 일); Wi Jo Kang, 「Church and State Relations: Japanese Colonial Period」, 24~25쪽(대표 모두가 경찰서에 불려 갔다고 적어 Grayson과 서술이 다름). 선택의 읽기: 목사 한 사람이 쓴 나삼진의 2018년 글(코람데오닷컴 논문란, 학술지 논문이 아님) 한 편에만 기대고 있다. 그 글이 허순길과 민경배, 『매일신보』를 인용해 적은 평북노회(1938년 2월 9일), 평양노회(8월)의 앞선 결의와 김길창의 안(『매일신보』 1938년 9월 13일)은 인용된 책과 신문을 이 책에서 열지 못했다. 이 글도 압박이 있었을 것임은 인정한다.\n8. 니케아-콘스탄티노플 신경(381)이 고백하는 한 분 하나님."
