            "t": "1945년 해방이 오자 북쪽에서 많은 신자들이 남쪽으로 내려왔습니다.¹ 북에서 남으로 내려오는 일을 월남이라 부릅니다. 한경직 목사는 해방 때 신의주에 있었고, 그해 10월 38선(남과 북을 가른 경계선)을 넘어 서울에 닿았습니다.¹ 한 미국 장로교 잡지는 그가 밤에 몰래 넘었다고 전했습니다.²\n\n서울에서 그는 해방으로 비게 된 건물에서 먼저 내려온 신자들과 함께 교회를 시작했습니다.¹ ² 잡지에 따르면 처음에는 마흔 명쯤의 피난민이 모여 드리던 기도 모임이었습니다.² 모인 사람들 가운데는 청년과 학생이 많았다고 합니다.² 북에서 온 신자들이 몰려들었고, 남쪽에서 살 길을 찾도록 돕는 모임도 서울에서 만들어졌습니다.¹ 남쪽에 닿은 사람들은 낯선 도시에서 먼저 예배할 자리와 잠잘 자리를 찾아야 했습니다.\n\n1950년 6월 25일 전쟁이 일어나자 길은 다시 남쪽으로 이어졌습니다.³ 북에서 내려와 겨우 자리를 잡았던 사람들은 다시 길을 나서야 했습니다. 서울의 교인들도 다시 피난길에 올랐고, 많은 사람이 부산까지 내려갔습니다.² ⁴\n\n교회는 길 위의 사람들에게 무엇을 내놓았을까요? 한 선교사는 1950년의 보고에서 피난 온 목사들을 맞은 교회들의 일을 적었습니다. 교회들은 월급은 줄 수 없어도 밥과 잠자리는 내놓을 수 있다며 목사들을 머물게 했다고 합니다. 이런 도움이 없었다면 그 목사들이 길에서 쓰러졌을 것이라고도 했습니다.⁴ 국제연합의 구호 기관이 피난민에게 배급을 했지만 모자랐다고도 같은 글은 적었습니다.⁴",
