            "t": "예레미야 29장은 예루살렘에서 바빌론으로 끌려간 사람들에게 예레미야가 보낸 편지입니다. 예언자는 이 말이 이스라엘의 하나님이 하시는 말씀이라고 밝힙니다. 편지는 그들을 끌려가게 하신 분이 하나님이라고 분명히 적습니다. 고향으로 돌아갈 수 없게 된 사람들에게 이 편지가 맡기는 것은 지금 있는 자리에서 사는 방법입니다.\n\n4~6절은 하나님이 끌려간 모든 사람에게 하시는 말씀으로 시작합니다. 특별한 몇 사람이 아니라 모두에게 주신 말입니다. 거처를 마련해 눌러 살고, 채소밭과 과일나무를 가꾸어 거두라고 합니다. 가정을 이루고 자녀들도 혼인시켜 가족이 줄지 않고 늘어나게 하라고 합니다.\n\n7절은 한 걸음 더 나아갑니다. 하나님이 끌려가게 하신 그 도시가 잘되도록 힘쓰고, 그 도시를 위해 기도하라고 합니다. 그 도시는 그들이 낯설게 여기던 곳이었습니다. 그런데도 그 도시가 평화로울 때에야 그들의 평화도 있다고 이유를 덧붙입니다.",
