            "t": "예레미야의 편지는 끌려간 사람들에게 두 가지를 맡깁니다. 하나는 그곳에서 살림을 꾸리는 일이고, 다른 하나는 그곳의 평안을 구하는 일입니다. 이 말은 위로에 그치지 않고 해야 할 일을 줍니다. 떠나온 곳을 그리워하는 사람들에게 이 편지는 지금 있는 자리를 삶의 자리로 받으라고 말합니다. 그곳이 평화로워야 자기들도 평안하다는 말은, 머무는 땅의 이웃과 함께 살며 기도하는 길을 가리킵니다.\n\n앞 카드의 사람들이 이 편지를 따라 쓴 것은 아닙니다. 다만 북에서 내려온 신자들은 천막을 빌려 예배할 자리를 만들고 피난 온 가족이 머물 수 있는 수용소를 열었습니다. 전쟁 때 교회들은 피난 온 목사들에게 밥과 잠자리를 내주었고, 천주교와 개신교의 구호 기구들은 옷과 먹을 것을 나누었습니다. 이 모습은 본문이 말하는 삶의 모양과 닿아 있습니다.\n\n우리와 같은 것, 다른 것. 같은 것은 성경이 오래 말해 온 것, 곧 낯선 곳에 머무는 사람들을 맞아 돌보는 마음입니다. 니케아-콘스탄티노플 신경이 고백하는 한 분 하나님을 믿는 믿음도 같습니다.⁷ 천주교와 개신교가 모두 구호 물자를 나누는 일에 나섰다는 점도 같습니다.⁵ ⁶ 다른 것은 구호가 오간 길입니다. 천주교는 구호 기구가 보낸 물자를 교회를 통해 나누었고, 개신교는 기독교세계봉사회 같은 여러 단체가 일했습니다.\n\n이 시대에서 배울 점. 결혼반지와 이불과 옷을 내놓으며 예배할 자리와 잠잘 자리를 마련한 교인들의 일은 이 교회들이 받은 선물입니다. 천막 아래에서도 함께 모여 예배한 일도 그렇습니다.",
