        "qs": [
          {
            "id": "ce09-q0",
            "t": "모임이나 가족 안에서 생각이 달라 서로 다른 길로 갈라지는 모습을 가까이서 본 적이 있나요? 그때 어떤 마음이 들었나요?",
            "sub": "모임 장소나 날짜를 두고 갈린 작은 일도 괜찮아요. 말하고 싶은 만큼만 이야기해요.",
            "vs": [],
            "lead": "갈라지는 자리에서 사람마다 지키고 싶은 것이 달랐다는 이야기로 이어 가세요. 오늘 읽을 교단들의 이야기도 같은 모양이에요. 아픈 기억을 자세히 꺼내게 하지 않아도 돼요."
          }
        ]
