            "id": "ce09-r4a",
            "kind": "read",
            "h": "본문의 자리",
            "t": "바울은 갇힌 몸으로 빌립보 교회에 편지를 씁니다(1장). 편지 곳곳에서 바울은 교회가 한마음으로 서기를 바란다고 말하고(1:27), 4장 2절에는 서로 마음을 같이하라는 부탁을 받은 두 사람의 이름도 나옵니다. 그런 편지 한가운데에서 2장 1절은 \"만일\"로 시작합니다. 그리스도 안에서 받은 격려, 사랑에서 나오는 힘, 성령 안에서 함께 나누는 삶, 깊은 연민이 정말 있다면, 하고 되묻는 것입니다.\n\n2절에서 바울은 그렇다면 자신의 기쁨을 채워 달라고 부탁합니다. 생각을 같이하고 같은 사랑으로 서로를 대하며 마음을 하나로 모아 달라는 것입니다.\n\n3절은 하지 말아야 할 것 둘을 말합니다. 이기려고 겨루는 마음과 헛된 자랑에서 나오는 일입니다. 대신 낮은 마음으로 서로를 자기보다 앞세우라고 합니다.\n\n4절은 마지막 당부입니다. 각자 자기에게 이로운 것만 살피지 말고, 이웃에게 이로운 것도 눈여겨보라고 합니다. 같은 편지를 읽는 사람들이 서로의 몫을 함께 돌아보게 하는 말입니다.",
