            "t": "1970년대에는 급격한 도시화와 산업화 속에서 많은 사람이 도시로 옮겨 왔습니다. 옛 가치관과 사회의 짜임이 흔들리던 때였고, 이 사람들은 새 이웃과 새 일터를 만났습니다.¹ 교회도 이 변화 속에서 여러 길로 사람들을 만났습니다.\n\n공장이 있는 도시에는 일터 곁으로 간 사람들이 있었습니다. 미국 감리교 선교사 조지 오글 목사는 이보다 앞서 1961년부터 10년 동안 인천에서 도시산업선교회(공장과 일터에서 선교하는 모임)를 이끌었습니다. 교회가 가난하고 힘없는 이들과 함께 서야 한다고 보았습니다.² 서울 영등포에서는 조지송 목사가 노동자 곁에서 같은 일을 이끌었습니다.³\n\n사람의 권리를 교회의 일로 말한 사람들도 있었습니다. 한국기독교교회협의회(여러 교단이 함께 일하려고 모인 협의체)는 1974년에 사람이 사람으로서 지닌 권리를 돌보는 인권위원회를 세웠습니다.⁴\n\n복음을 알리는 일에 힘쓴 사람들도 있었습니다. 김준곤 목사는 1962년부터 한국대학생선교회를 이끌며 온 민족의 복음화를 내세웠습니다.⁵ 이 모임은 1974년 8월 13일부터 18일까지 서울 여의도 광장에서 엑스플로74라는 전도 훈련 대회를 열었습니다.⁶\n\n이 길들은 같은 시대의 사람들 앞에 있었습니다. 어떤 이는 일터의 사정을, 어떤 이는 사람의 권리를, 어떤 이는 복음을 알리는 일을 먼저 마음에 두었습니다. 세 길 모두 도시 한가운데서 이루어졌고, 이어지는 글에서 그 길을 걸은 사람들이 남긴 말을 읽습니다.",
