            "h": "자기를 돌아본 교회들",
            "t": "한국기독교교회협의회는 한국 개신교의 여러 교단과 정교회가 함께 일하려고 모인 협의체입니다. 1988년 2월 29일 이 협의회의 총회에서 통일과 평화에 관한 선언이 참석한 회원의 만장일치로 채택되었습니다. 해방과 분단 뒤 마흔세 해가 지난 때였습니다.¹\n\n선언은 믿음을 고백하는 말로 시작해 여섯 부분으로 이어집니다. 첫 부분에는 개신교가 이 땅에 복음을 전한 지 백 년이 넘는 동안의 잘못을 돌아보는 말이 있습니다. 세 번째 부분은 분단과 증오 앞에서 죄를 고백하는 글입니다. 이웃을 사랑하지 못한 일이 그 고백에 들어 있습니다.²\n\n같은 무렵 교회 문 앞에는 새 이웃이 오고 있었습니다. 외국인 노동자가 들어오기 시작한 1980년대 말부터 한국은 서서히 다문화 사회(여러 나라 출신이 함께 사는 사회)가 되었습니다. 대부분의 교회는 이 변화에 더디게 반응했고, 한 민족이라는 생각이 강했던 것도 그 까닭의 하나였습니다.³\n\n2010년에 진보적 개신교 다문화 교회들을 조사한 연구는, 이 교회들이 이주민을 신자로 맞으려는 마음보다 섬길 이웃으로 보는 마음이 더 컸다고 봅니다. 한국인 중심의 문화가 남아 있어 더 돌아봐야 한다는 말도 있습니다.⁴ 분단의 이웃 앞에서도 새 이웃 앞에서도, 돌아보는 말이 나왔습니다.",
