            "t": "1. 선언의 이름은 「민족의 통일과 평화에 대한 한국기독교회 선언」이고, 한국기독교교회협의회 제37회 총회에서 1988년 2월 29일 발표되어 참석한 회원의 만장일치로 채택되었다: 한국민족문화대백과사전 「민족의 통일과 평화에 관한 한국기독교회선언」 항목(백과사전 항목). 협의회가 한국 개신교 교회들과 정교회의 협의체라는 것: 같은 사전의 「한국기독교교회협의회」 항목. 영어 번역본: \"Declaration of the Churches of Korea on National Reunification and Peace\" (NCCK, 1988. 2. 29, 미국 장로교회 누리집에 게시된 PDF). \"마흔세 해\"는 1945년 해방부터 1988년까지의 계산이다. 이주민 교회 연구는 논문 초록으로 확인했다.\n2. 선언의 구성: 백과사전 항목(신앙고백으로 시작해 여섯 부분: 정의와 평화를 위한 선교의 전통, 분단의 현실, 분단과 증오에 대한 죄책 고백, 통일의 기본 원칙, 남북 정부에 대한 건의, 교회의 과제). 영어 번역본에서도 맨 앞의 신앙고백 서문 뒤에 같은 여섯 제목이 이어지고, 첫 부분에 개신교가 복음을 전한 백여 해 동안 한국 사람들 앞에서 많은 잘못을 저질렀다는 문장이, 세 번째 부분에 이웃을 사랑하지 못하고 미워하고 속인 일 등의 고백 항목이 있다. 독자 글은 이 가운데 \"돌아보는 말\"과 \"이웃을 사랑하지 못한 일\"만 줄여 썼다. 한국어 번역문을 옮기지 않고 풀어 썼다.\n3. Hwarang Moon, \"Toward the Vision of Revelation: Multicultural Worship in a Korean Context\", *Religions* 13(2), 2022, 171의 도입부(1980년대 말 외국인 노동자의 입국, 1995년 무렵 이후 국제결혼의 증가, 한국 교회의 더딘 반응과 한 민족이라는 생각이 강했던 점).\n4. 김경주·오세일·김우선, 「이주민에 대한 한국교회의 대응: 다문화교회의 형성 사례 연구」, 『종교연구』 75권 2호(2015), 95~134쪽의 초록. 이 연구는 2010년 3월부터 8월까지 진보적 개신교 다문화 교회를 현장 조사한 것이다.\n5. Moon(2022)의 2절 사례 연구와 4.2절: 2019년 1월 세워진 교회, 2019년 7월 예배를 합치고 한국어 설교를 영어로 동시통역하자 설교 시간이 두 배가 되었으며 흐름이 끊겼다는 서술, 2020년 5월 다시 나눔, 달마다 첫째 주 통합 예배와 성찬과 식사, 화면 가사와 번역, 성찬을 눈에 보이는 하나 됨의 모습으로 설명한 말, 다른 주의 아침과 오후 예배, 작은 다문화 교회의 재정과 일손 부족. 논문의 제목(Toward the Vision of Revelation)을 \"요한계시록의 환상을 향하여\"로 옮겼다. 논문이 이 교회와 첫 예배 방식에 내린 평가의 말은 독자 글에 옮기지 않았다.\n6. 선언의 여섯째 부분 「교회의 과제」(영어 번역본과 백과사전 항목): 희년으로 삼은 1995년, 평화와 통일을 위한 기도 주일의 예배 구성, 교회 갱신, 평화와 통일을 위한 교육, 북쪽 신자들을 위한 기도와 흩어진 가족과 교인을 찾는 일. 선언은 남북 정부에 드리는 건의도 담았으나 이 과는 교회가 스스로에게 한 약속만 읽었다.\n7. 표는 선언의 여섯째 부분(각주 6)에서 골랐다. 본문 설명의 사실은 각주 2, 4, 5. 마태복음 5:13~16의 풀이는 번역 어구와 짜임을 바꿔 썼다."
