            "t": "1924년 9월 24일, 서울 새문안교회에 사람들이 모였습니다. 장로교와 감리교의 선교부(다른 나라에서 와 복음을 전하는 일꾼들의 단체)와 한국 교회 대표들이 앉았습니다. 기독교 청년 단체와 성경을 펴내는 단체의 대표도 함께했습니다.¹ 서로 다른 교파가 한 나라에서 같은 복음을 전하고 있으니 힘을 모으자는 자리였고, 이 모임을 조선예수교연합공의회(한국 교회들의 연합 모임)라 불렀습니다. 목적은 함께 복음을 전하고, 사회의 도덕을 높이고, 기독교 문화를 알리는 것이었습니다.¹\n\n왜 교회를 하나로 합치지 않고 함께 일하기로 했을까요? 규칙은 교회를 합치는 일보다 함께 일하는 데 무게를 두었습니다. 각 교파의 믿음의 글과 교회 운영과 예식에는 끼어들지 않기로 했습니다.¹ 각자 지켜 온 믿음의 모양은 그대로 두고 함께할 일만 함께하자는 뜻이었습니다. 먼 바람으로는 이 땅에서 하나 된 교회를 이루는 꿈도 있었다고 합니다.¹\n\n이 모임은 일제의 간섭으로 문을 닫았다가 1946년 다시 이어졌고, 한국기독교교회협의회가 이 모임을 잇습니다. 협의회는 한국 개신교 교회들과 정교회의 협의체입니다.² 그 뒤 이 땅의 천주교회와 개신교 일부 교단이 한 성경을 함께 옮기는 일도 있었습니다. 번역위원회는 1968년 구약 쪽이 먼저, 이듬해 신약 쪽이 조직되었고, 1977년 부활절에 구약까지 담은 『공동번역 성서』가 나왔습니다.³",
