            "h": "1984년, 일치를 말한 두 자리",
            "t": "1984년 5월 6일 시성 미사를 드린 그날, 서울의 교황청 대사관 성당에 다른 교회의 지도자들이 모였습니다. 요한 바오로 2세는 에베소서의 한 주님과 한 믿음과 한 세례를 떠올리며 인사말을 열었습니다. 그 해는 장로교와 감리교가 이 땅에서 백 년을 맞는 해였고, 교황은 먼저 그 기쁨을 나누었습니다.⁴\n\n교황은 이 땅 사람들이 선교사보다 먼저 평신도가 퍼뜨린 한글 성경으로 그리스도를 알았다고 말했습니다. 처음 온 선교사들과 그 뒤를 이은 사람들이 의료와 교육과 여성의 일에 남긴 열매도 기렸습니다. 이어 여러 교회가 함께 옮긴 한국어 성서가 널리 받아들여지고 있는 것이 반갑다고 했습니다. 서로 다른 교회 사람들이 함께한 신학 작업과 대학들의 협력도 격려했습니다.⁴\n\n마지막에 교황은 요한복음 17장 21절을 가리키며, 서로의 확신과 양심을 존중하면서 믿음과 사랑 안에서 온전히 하나 되기를 바란다고 했습니다. 그리스도의 일이 믿을 만하게 보이는 것은 제자들이 하나 되는 데 달려 있다는 말도 했습니다.⁴\n\n그해 8월 15일부터 19일까지는 여의도에서 한국기독교 100주년 선교대회가 열렸습니다. 10과에서 만난 그 대회입니다. 한국기독교 100주년 기념사업회가 맡았고 여러 교단이 함께했습니다. 사업의 지향 가운데에는 \"교회분열의 역사에 대한 참회와 하나의 교회\"가 있었습니다.⁵ 같은 해에 교황은 다른 교회 지도자들 앞에서, 개신교의 사업회는 대회의 지향으로, 각자의 말로 일치를 꺼냈습니다."
