            "t": "20절의 기도 속에는 훗날 믿음에 이를 사람들, 곧 오늘의 우리도 들어 있다고 읽을 수 있습니다. 예수님의 기도에서 하나 됨은 교회가 스스로 만들어 내는 일이기 전에, 아버지와 아들의 사귐에서 흘러나오는 일입니다. 1984년의 인사말도 이 구절을 가리키며 믿음과 사랑 안에서 하나 되기를 빌었습니다.⁸\n\n이 교재는 선비들이 책을 읽던 방에서 시작했습니다. 박해 속의 모임과 한글 성경, 학교와 병원, 평양의 회개를 지났습니다. 나라를 잃은 시대와 전쟁과 피난, 갈라짐의 아픔, 도시로 간 교회를 거쳐 오늘의 질문에 이르렀습니다. 그 길에는 서로 다른 교회들이 함께 있었고, 마지막 과는 그 모두를 한 기도 안에서 읽었습니다.\n\n우리와 같은 것, 다른 것. 같은 것은 이 기도를 성경으로 함께 받는 일과, 천주교와 개신교와 정교회가 함께 받아 온 니케아-콘스탄티노플 신경이 교회를 하나라고 고백하는 일입니다.⁸ 다른 것은 하나 되는 길을 걷는 모양입니다. 1959년 장로교는 세계 교회의 연합 기구인 세계교회협의회와 어떻게 지낼지를 두고 갈렸습니다. 한쪽은 세계 교회와의 협력을 이어 가자고 했고, 다른 쪽은 세계교회협의회의 신학을 받아들이지 않았습니다.⁸ 함께 옮긴 성경도 오늘 교회마다 쓰는 번역이 다릅니다.⁸\n\n이 시대에서 배울 점. 각자 지켜 온 믿음을 두고 함께할 일을 찾은 1924년의 모임이 있었습니다. 서로의 확신과 양심을 존중하자는 1984년의 인사말도 있었습니다. 이 둘과 한 책을 함께 옮긴 일은 이 길에서 받은 선물입니다.",
